#include "package.hpp"
#include <cstdio>
int main(int argc,char**argv){if(argc!=2)return 2;srhd_awa::package::Package p;std::string e;if(!p.Open(std::string(argv[1])+"/DATA/common.pkg",&e)){std::fprintf(stderr,"%s\n",e.c_str());return 1;}auto s=p.Summarize();if(!s.entries||!s.files||!s.tree_hash||!p.Resolve("data")||!p.Resolve("DATA/Asteroid/00.gai")||!p.Resolve("data\\asteroid\\00.gai")||p.Resolve("DATA/Asteroid/00.gai/nope")){std::fprintf(stderr,"tree/lookup invalid\n");return 1;}uint32_t h[16]{};for(auto&x:h)if(!(x=p.OpenEntryByPath("DATA/Asteroid/00.gai",&e))){std::fprintf(stderr,"open failed\n");return 1;}if(p.OpenEntryByPath("DATA/Asteroid/00.gai",&e)||e!="package open-slot limit"){std::fprintf(stderr,"slot limit invalid\n");return 1;}p.CloseEntry(h[3]);if(p.OpenEntryByPath("DATA/Asteroid/00.gai",&e)!=h[3])return 1;std::printf("folders=%u files=%u entries=%u depth=%u hash=%016llx\n",s.folders,s.files,s.entries,s.max_depth,static_cast<unsigned long long>(s.tree_hash));return 0;}
